update content_bodies set title = '【豪姫が「愛」を歌う】だから岡山城　The Singing Princess', description = '新・岡山城PRサイト　https://kin-ujo.jp/ 

2022年11月のリニューアルオープンに向けて大規模改修中の岡山城。

岡山城の築城主・宇喜多秀家の妻である「豪姫」をテーマとしたミュージックビデオ「だから岡山城」。
二人の関係をドラマティックに表現したMVとなっています。

「岡山城は変わっても、ふたりの愛は変わらない――」
岡山城の改修の様子も織り交ぜながら、時代をこえた想いを表現しています。

豪姫の役には、岡山県出身でタレントの「梶原凪」さんを起用。
劇中で踊るダンスは、梶原凪さん自身による振り付けです。

※MVに映っている岡山城天守閣は、組立作業中です。

※前作を見るとより楽しめるかも。あわせてご覧ください。
