update content_bodies set title = 'The Singing Princess: The Castle of Okayama, Where the Princess Sings of Love', description = 'New Okayama Castle PR site https://kin-ujo.jp/ 

Okayama Castle is undergoing a major renovation in preparation for its grand reopening in November 2022.

The music video "The Castle of Okayama" is themed around "Go-hime," the wife of the castle''s builder, Ukita Hideie.
It dramatically expresses the relationship between the two.

"Even if Okayama Castle changes, their love remains unchanged—"
While incorporating scenes of the castle''s renovation, it expresses timeless feelings.

The role of Go-hime is played by Nagi Kajiwara, a talent from Okayama Prefecture.
The dance performed in the video is choreographed by Nagi Kajiwara herself.

*The Okayama Castle keep shown in the MV is currently under assembly.

*You may enjoy it even more if you watch the previous work. Please check it out as well.
↓ ↓ ↓
"Ninja Seriously Tried Singing: Farewell Okayama Castle"
