update content_bodies set title = '【岡山城】磯田道史氏による歴史解説 Explanation about the history of Okayama Castle by Michifumi Isoda of a historian', description = '歴史家の磯田道史氏により岡山城をわかりやすく解説。天守閣や月見櫓、石垣の変遷などを説明しています。ここではダイジェスト版で紹介していますが６編からなる詳しい内容は、岡山城天守閣でご覧いただけます。第1編 対岸から眺めた岡山城、第2編 石山の城、第3編 天守閣東側石垣、第4編 月見櫓下石垣・廊下門、第5編 中の段、第6編 本殿・天守閣。

Under the direction of Hideie Ukita, a daimyo of the Sengoku Period, Okayama Castle was completed in 1597 after eight years of construction. Because the castle was oriented to the west, Hideie undertook a major project to pull the nearby Asahigawa River to flow along the eastern end of the castle to ward off enemies from entering through the rear. The architecture of the period is partly represented by the use of boards painted with black lacquer on the walls of the castle tower (Tenshukaku). As such, the exterior is black, and in the later periods, the castle came to be known as the Crow Castle (Ujo). Hideie not only used Okayama Castle as a military facility, but also called in merchants and craftsmen around the castle''s domain to develop a castle town.

After the Ikeda Family took control over the castle, Okayama Korakuen Garden,a vast daimyo garden, was built to the north across the Asahigawa River at the end of the 17th century.

Under the aegis of historical castle lords, Okayama continued to thrive as a city, laying down the foundations of a modern city.

#okayama castle #japanese castle #japan #okayama' where id = 'b9uYURIU8stQtxxQiYbW6';
update content_bodies set title = 'Explanation about the history of Okayama Castle by Michifumi Isoda of a historian', description = 'A clear explanation of Okayama Castle by historian Michifumi Isoda.
It explains the changes in the main keep, the moon-viewing turret, and the stone walls.
Here, we introduce a digest version, but the detailed content consisting of six parts can be viewed at the Okayama Castle main keep.
Part 1: Okayama Castle viewed from the opposite shore,
Part 2: The castle of Ishiyama,
Part 3: The stone walls on the east side of the main keep,
Part 4: The stone walls under the moon-viewing turret and the corridor gate,
Part 5: The middle level,
Part 6: The main hall and the main keep.

Under the direction of Hideie Ukita, a daimyo of the Sengoku Period, Okayama Castle was completed in 1597 after eight years of construction.
Because the castle was oriented to the west, Hideie undertook a major project to pull the nearby Asahigawa River to flow along the eastern end of the castle to ward off enemies from entering through the rear.
The architecture of the period is partly represented by the use of boards painted with black lacquer on the walls of the castle tower (Tenshukaku).
As such, the exterior is black, and in the later periods, the castle came to be known as the Crow Castle (Ujo).
Hideie not only used Okayama Castle as a military facility, but also called in merchants and craftsmen around the castle''s domain to develop a castle town.

After the Ikeda Family took control over the castle, Okayama Korakuen Garden, a vast daimyo garden, was built to the north across the Asahigawa River at the end of the 17th century.

Under the aegis of historical castle lords, Okayama continued to thrive as a city, laying down the foundations of a modern city.

#okayama castle #japanese castle #japan #okayama' where id = 'vg7-jeLrBCA91oEqFr8rU';
