update content_bodies set title = '空から見たみちのく潮風トレイル～春・夏・秋～／Michinoku Coastal Trail From the Sky: Spring, Summer, Fall', description = '普段の歩く旅では見ることのできない上空からの視点で、みちのく潮風トレイルの魅力をお伝えします。春の桜の風景から始まり、入り組んだリアスの森と海、穏やかな湾の水面に映る夕映え、岩に打ち寄せる白波など、トレイル沿線の変化に富んだ海の表情を鳥になった気分でご覧いただけます。
This is a perspective you don’t get to see on foot: let us show you how lovely the Michinoku Coastal Trail is from the sky. We start with scenes of cherry blossoms in the spring, then the forest and sea along the meandering ria coastline, the glowing sunset reflecting from calm bay waters, and white waves crashing against the rocks. Enjoy the many faces of the ever changing ocean along the Michinoku Coastal Trail from a bird’s perspective. 

#みちのく潮風トレイル　
#MichinokuCoastalTrail
#Japanese#Long#Distance#Trail' where id = 'EejRiEjvd-ZGrd_nQWDPf';
update content_bodies set title = 'Michinoku Coastal Trail From the Sky: Spring, Summer, Fall', description = 'This is a perspective you don’t get to see on foot: let us show you how lovely the Michinoku Coastal Trail is from the sky.
We start with scenes of cherry blossoms in the spring, then the forest and sea along the meandering ria coastline, the glowing sunset reflecting from calm bay waters, and white waves crashing against the rocks.
Enjoy the many faces of the ever changing ocean along the Michinoku Coastal Trail from a bird’s perspective.' where id = 'KdjUFanQi-utZFo_ufKZW';
update content_bodies set title = 'みちのく潮風トレイル南部～春・夏・秋～／MCT Southern Part: Spring, Summer, Fall', description = 'みちのく潮風トレイル沿線の自然風景、地域の人とのふれ合いやハイカー同士の交流など、ハイカーの日常が切り取られた映像です。みちのく潮風トレイル南部ならではの島歩きや、相馬野馬追まつりなどの風景も収録された一本です。（撮影地：福島県相馬市～岩手県大船渡市）
See everyday moments for hikers following the Michinoku Coastal Trail, including natural scenery along the trail, conversations with local people and time spent with other hikers.
This video also shows hiking on various islands characteristic of the southern part of the trail and the Soma Nomaoi Festival, an ancient horse festival. (Filmed in areas between Soma, Fukushima Prefecture and Ofunato, Iwate Prefecture)

#みちのく潮風トレイル　
#MichinokuCoastalTrail
#Japanese#Long#Distance#Trail' where id = 'z4lxG1KIC1v3_lHxQOi-c';
update content_bodies set title = 'MCT Southern Part: Spring, Summer, Fall', description = 'This video captures everyday moments for hikers following the Michinoku Coastal Trail, including natural scenery along the trail, conversations with local people and time spent with other hikers.
This video also shows hiking on various islands characteristic of the southern part of the trail and the Soma Nomaoi Festival, an ancient horse festival. (Filmed in areas between Soma, Fukushima Prefecture and Ofunato, Iwate Prefecture)' where id = 'BG7KeSCfvEyv9pp3IrhbI';
update content_bodies set title = '地域の声を聞く／Interviews of Locals | みちのく潮風トレイル', description = 'ハイカーに美味しい料理を提供する人、道づくりに関わった人、休憩場所を提供する人、トレイルを日々守る人、山道を整備する人、地場産業を支える人、ハイカーを島から島へと渡す人・・・そして、ハイカーを見かけると声を掛けてくれる地域の人。みちのく潮風トレイルにはたくさんの「トレイルエンジェル」がいます！
There are people who feed hikers delicious food, those who helped make the trail, who provide spots to rest, those who protect and preserve the trail each day, those who maintain mountain hiking courses, those who support local industry and those who ferry hikers from island to island. And let’s not forget the local people who come up and talk to hikers.
There are so many trail angels along the Michinoku Coastal Trail!

#みちのく潮風トレイル　
#MichinokuCoastalTrail
#Japanese#Long#Distance#Trail' where id = 'TbYlApLAtXWkF7QQd16L9';
