update content_bodies set title = '空から見たみちのく潮風トレイル～秋・冬～／Michinoku Coastal Trail From the Sky: Autumn and Winter', description = 'ドローン映像ならではの迫力ある壮大な海岸線や河口の風景、そしてどこまでも続く防潮堤や震災遺構など、青森県八戸市から福島県相馬市まで1,000kmを超えるみちのく潮風トレイルの道の多様性が凝縮されたおすすめの動画です。時々映るハイカーの小ささから現地のスケールを感じてください。
See the impressive footage we can expect from drones: majestic scenes of coastline and river mouths, as well as seemingly endless stretches of seawall and tsunami monuments. A highly recommended video because it shows, in a condensed form, the variety of the over 1000 kilometer long Michinoku Coastal Trail running from Hachinohe in Aomori Prefecture to Soma in Fukushima Prefecture. Get a grasp of the massive scale of this landscape by watching for occasional appearances by miniature hikers.

#みちのく潮風トレイル　
#MichinokuCoastalTrail
#Japanese#Long#Distance#Trail' where id = 'IgrwP5Ok0ss93GoYlv7Ub';
update content_bodies set title = 'Michinoku Coastal Trail From the Sky: Autumn and Winter', description = 'See the impressive footage we can expect from drones: majestic scenes of coastline and river mouths, as well as seemingly endless stretches of seawall and tsunami monuments. A highly recommended video because it shows, in a condensed form, the variety of the over 1000 kilometer long Michinoku Coastal Trail running from Hachinohe in Aomori Prefecture to Soma in Fukushima Prefecture. Get a grasp of the massive scale of this landscape by watching for occasional appearances by miniature hikers.' where id = 'y-TpI4i8FL1x4hlxwJefD';
update content_bodies set title = 'みちのく潮風トレイル南部～秋・冬～／MCT Southern Part: Autumn and Winter', description = 'みちのく潮風トレイル南部の秋から冬にかけての風景を、一人のハイカーの旅を通してお伝えします。南部のルートには史跡や震災遺構などが点在し、里山や集落などを通るため、人の営みをより身近に感じることができます。（撮影地：福島県相馬市～岩手県大船渡市）
See scenes from the southern part of the Michinoku Coastal Trail in fall and winter as we follow the progress of a single hiker. The southern part of this trail has many historical sites and tsunami monuments, and because it goes through rural landscapes and villages, you can more closely experience people’s daily lives. (Filmed in areas between Soma, Fukushima Prefecture and Ofunato, Iwate Prefecture)

#みちのく潮風トレイル　
