update content_bodies set title = '【5分でわかる】世界遺産  熊野古道・熊野三山【最強パワースポット】', description = '和歌山県の観光に欠かせない、熊野三山（熊野本宮大社。熊野速玉大社・熊野那智大社）の魅力をコンパクトに5分でお伝えします。
熊野三山は1000年以上の歴史を持つ熊野詣での聖地で、熊野古道は熊野三山を巡る参詣道。
世界文化遺産「紀伊山地の霊場と参詣道」にも登録され、癒やしと蘇りのパワースポットです。

