update content_bodies set title = '[5 Minutes to Understand] World Heritage Kumano Kodo & Kumano Sanzan [The Ultimate Power Spot]', description = 'In just 5 minutes, we will compactly convey the charm of Kumano Sanzan (Kumano Hongu Taisha, Kumano Hayatama Taisha, and Kumano Nachi Taisha), which is essential for tourism in Wakayama Prefecture.
Kumano Sanzan is a sacred site of Kumano pilgrimage with over 1,000 years of history, and the Kumano Kodo is the pilgrimage route that connects the three shrines.
It is also registered as a UNESCO World Heritage Site under ''Sacred Sites and Pilgrimage Routes in the Kii Mountain Range,'' serving as a power spot for healing and revival.

If you have any other spots in Wakayama that you would like us to introduce or questions you would like to ask, please let us know in the comments!

