update content_bodies set title = '紀州浪漫2022春号　わかやま庭園回遊', description = '和歌山県にある名園を巡る旅。日差しが暖かくなれば外に出かけたくなりませんか。そんなときは美しいお庭を眺めて静かに散策をするのがおすすめ！またその地域ならではのグルメ巡りも楽しみのひとつ。春はわかやま庭園回遊を！

