update content_bodies set title = 'Kishu Romance Spring 2022 - Wakayama Garden Tour', description = 'A journey to visit the famous gardens in Wakayama Prefecture. As the sunlight becomes warmer, don''t you feel like going outside? At such times, it''s recommended to quietly stroll while admiring the beautiful gardens! Additionally, enjoying local gourmet food is one of the highlights. Spring is the perfect time for the Wakayama Garden Tour!' where id = 'F8BxrscymQjesLApLV0Nh';
update content_bodies set title = 'サイクリング王国わかやま　Route.4　熊野三山巡り', description = '世界遺産の地「熊野」をサイクリングするのは、ベキさんと筧五郎さん。那智の滝でパワーをもらったら、熊野速玉大社を経由して、熊野本宮を目指します。川湯温泉や湯の峰温泉で癒されながら、大自然の中をサイクリングしませんか！

わかやまサイクリング王国　https://wakayama800.jp/

