update content_bodies set title = 'Cycling Kingdom Wakayama Route.4 Kumano Sanzan Tour', description = 'Cycling through the World Heritage site of ''Kumano'' with Beki-san and Kakei Goro-san. After gaining energy at Nachi Falls, we will head towards Kumano Hongu via Kumano Hayatama Taisha. How about cycling through the great outdoors while being healed at Kawayu Onsen and Yunomine Onsen?' where id = 'X9y1SJUxN_oBb3rNhihbm';
update content_bodies set title = '紀州浪漫 2021秋　「心浄める聖地の旅～高野山～」', description = '秋は高野山が一段と美しい季節。穴場的フォトジェニックスポットのケーブルカーで聖地「高野山」にでかけませんか。' where id = 'xYx4g_TSRLDJxGiiayqNk';
update content_bodies set title = 'Kishu Romance Autumn 2021: "A Journey to the Sacred Land that Purifies the Heart - Mount Koya"', description = 'Autumn is a particularly beautiful season for Mount Koya. Why not take a trip to the sacred land of "Mount Koya" via the cable car, a hidden gem for photogenic spots?' where id = 'gdNs7i_ErrtxS-7MAVSVB';
update content_bodies set title = 'サイクリング王国わかやま　WAKAYAMA800を走る　～紀の川サイクリングロードから夕陽を追って海へ～', description = '和歌山県でおすすめサイクリングロードを平野由香里さんがライドします。映える駅“隅田駅”から紀の川サイクリングロードを西へ。桃の産地 紀の川市では人気の藤桃庵のジェラートで一休み。美しい夕陽を追って和歌浦方面へ快適にサイクリングします。
