update content_bodies set title = 'Cycling Kingdom Wakayama - Riding WAKAYAMA800 - Following the Sunset from the Kinokawa Cycling Road to the Sea', description = 'Yukari Hirano rides along the recommended cycling roads in Wakayama Prefecture. Starting from the photogenic station ''Sumida Station'', we head west on the Kinokawa Cycling Road. In the peach-producing city of Kinokawa, we take a break with the popular gelato from Fujitomokan. We enjoy a comfortable cycling experience towards Wakayura while chasing the beautiful sunset.' where id = 'Rmdd0hhqTJWosaO6SAwgq';
update content_bodies set title = 'サイクリング王国わかやまWAKAYAMA800【ローディー編】', description = '和歌山県はサイクリストを歓迎する「サイクリング王国わかやま」。ローディーも初心者も…あらゆるタイプのサイクリストが楽しめるコースが無限大にあります！ぜひ、和歌山県でサイクリングをお楽しみください。' where id = 'srm_5LXZdoDVeFj3Co55_';
update content_bodies set title = 'Cycling Kingdom Wakayama WAKAYAMA800 [Roadie Edition]', description = 'Wakayama Prefecture welcomes cyclists as the ''Cycling Kingdom Wakayama.''
Whether you''re a roadie or a beginner... there are endless courses for all types of cyclists to enjoy!
Please enjoy cycling in Wakayama Prefecture.' where id = 'rjjs-tLxe0U3uvp_MlzoU';
update content_bodies set title = '【熊野】Photographic Video Magazine -KUMANO- 2014', description = '毎年、3月から5月の3ヶ月間以外の立ち入りが一切禁止されている神域に、特別の許可を得て、11月の晩秋シーズンに入域した際の映像です。
見事な色彩を放つ扇型の滝壺に降り注ぐ「二の滝」。そして、さらにその奥に佇む「三の滝」では、太陽の光と水しぶきの完全なる調和により、「奇跡の虹」を映像として捉えることにも成功しました。' where id = 'W7NXDCIAtWK0irLvB01LH';
update content_bodies set title = '[Kumano] Photographic Video Magazine -KUMANO- 2014', description = 'This footage was taken in November during the late autumn season, with special permission to enter a sacred area that is completely off-limits for three months each year, from March to May.
The "Ni no Taki" waterfall, with its stunningly colorful fan-shaped basin, cascades down. Furthermore, at the back lies the "San no Taki" waterfall, where we successfully captured the "Miracle Rainbow" on film, thanks to the perfect harmony of sunlight and water splashes.' where id = 'xS9UJBtlzQkcrC7yD3arn';
update content_bodies set title = 'Lavender Festa Kamifurano 2023  Liting up&Fireworks with Nene&Waka', description = '上富良野の夏を彩る新たなイベント「ラベンダーフェスタかみふらの2023」 ラベンダーが上富良野町の花になってから、今年で42年。町民はもちろん、日本全国、そして海外でも親しまれてきた町の花を、今年も期間限定で夜間もお楽しみいただけます。
7月15日（土）は上富良野産ホップや大麦を使用したビールを楽しむブースを1日限定で開設します。
幻想的なライティングで艶やかに彩るラベンダーの大パノラマを楽しみませんか。

北海道を中心に音楽活動をしているユニット「Nene＆Waka（ネネ＆ワカ）」によるスペシャルライブを特別にライブ配信いたします。どうぞお楽しみに！

#Nene＆Waka
#lavender   
#fireworks' where id = '2m_dDfWeDgLrcAKNal4M4';
update content_bodies set title = 'Lavender Festa Kamifurano 2023  Liting up&Fireworks with Nene&Waka', description = 'A new event that colors the summer of Kamifurano, "Lavender Festa Kamifurano 2023". This year marks the 42nd anniversary since lavender became the town flower of Kamifurano. Residents, as well as people from all over Japan and abroad, have cherished this town flower, and this year you can enjoy it at night for a limited time.
On July 15th (Saturday), we will set up a booth for one day only where you can enjoy beer made with locally produced hops and barley.
Would you like to enjoy the grand panorama of lavender beautifully illuminated with enchanting lighting?

We will also have a special live stream of a performance by the unit "Nene & Waka," who are active in the music scene centered around Hokkaido. Please look forward to it!

#Nene＆Waka
#lavender   
#fireworks' where id = '2rG6f-do7-1MXJAdKc7z4';
update content_bodies set title = 'Lavender Festa Kamifurano 2022  Liting up&Fireworks with Yui Makino', description = '上富良野の夏を彩る新たなイベント「ラベンダーフェスタかみふらの2022」 ラベンダーが上富良野町の花になってから、今年で41年。町民はもちろん、日本全国、そして海外でも親しまれてきた町の花を、今年も期間限定で夜間もお楽しみいただけます。
7月17日（日）は上富良野産ホップや大麦を使用したビールを楽しむブースを1日限定で開設します。
幻想的なライティングで艶やかに彩るラベンダーの大パノラマを楽しみませんか。

かみふらの特任PR大使 牧野由依さんのミニライブが予定されていましたが、都合により来られなくなりましたのでご報告いたします。

#lavender   
#hokkaido
#fireworks' where id = 'UqFmYq0OQrjp6TL4APSFB';
update content_bodies set title = 'Lavender Festa Kamifurano 2022  Liting up&Fireworks with Yui Makino', description = 'A new event that colors the summer of Kamifurano, "Lavender Festa Kamifurano 2022". This year marks the 41st anniversary since lavender became the town flower of Kamifurano. Residents, as well as people from all over Japan and abroad, have cherished this town flower, and this year you can enjoy it at night for a limited time.
On July 17th (Sunday), we will set up a booth for one day only where you can enjoy beer made with locally produced hops and barley.
Would you like to enjoy the grand panorama of lavender beautifully illuminated with fantastic lighting?

We regret to inform you that Yui Makino, the special PR ambassador of Kamifurano, was scheduled to have a mini live performance but will not be able to attend due to circumstances.

#lavender
#hokkaido
#fireworks' where id = 'S3Tki5O_mt5Q4DZkQteJ_';
update content_bodies set title = 'ラベンダーフェスタかみふらの2021 Special Omnibus Edjition', description = 'ラベンダーフェスタかみふらの2021 Special Omnibus Edjition

2021年7月17日（土）にLive配信した、日の出ラベンダー園のライトアップと花火大会の映像を再編集。迫力あるドローンから見た花火の映像をご覧ください。

最後にLive配信総集編、「ラベンダーフェスタかみふらの2021 Special Omnibus Edjition」が配信されますので最後までご覧ください。「らべとん」の新しいアニメーションも登場します。' where id = 'DF2KAVtvZskEcFq46cjYy';
update content_bodies set title = 'Lavender Festa Kamifurano 2021 Special Omnibus Edition', description = 'Lavender Festa Kamifurano 2021 Special Omnibus Edition

On July 17, 2021 (Saturday), we re-edited the footage of the sunrise lavender garden''s illumination and fireworks festival that was live-streamed. Enjoy the spectacular drone footage of the fireworks.

Finally, the live stream compilation, "Lavender Festa Kamifurano 2021 Special Omnibus Edition," will be broadcast, so please watch until the end. A new animation of "Rabeton" will also make an appearance.' where id = '_MB3b8RTogbpHvpJtbXVe';
