update content_bodies set title = 'FLOWERLAND KAMIFURANO FIREWORKS ONLINE 2020', description = '★★★ 絶景！パノラママウンテンビューと丘を彩る10万㎡の花畑に花火が打ちあがる！★★★
世界中でコロナウイルスが猛威を振るう中、「悪疫退散」「無病息災」「五穀豊穣」という世界の平和を願い花火を打上げます。
上富良野町を愛してくださる全世界の方へ、広大な花園に配置されたランタンと、そこから打ちあがる花火を今まで見たことのない角度からドローンの空撮で全世界に向けYouTubeでライブ配信されます。

★★★ お願い ★★★
当日会場は駐車場を含めて立ち入り禁止となります。
会場内ではライブの音や音楽は流れません、ご自宅のYouTubeが見られるテレビかパソコン、携帯端末でご覧ください。
会場周辺の路駐も通行の妨げになりますし、警察のパトロールも行いますのでご遠慮ください。
※天候・ネット環境により配信が切断・中止になる場合がございます。

★★★ Youtubeライブによる特別WEB中継 ★★★
「FLOWERLAND KAMIFURANO FIREWORKS ONLINE 2020」のWEB中継は、動画共有サイト「Youtube」の（一社）かみふらの十勝岳観光協会チャンネルにて行います。かみふらの十勝岳観光協会チャンネルに登録すると、中継を開始したときに通知を受け取ることができるので、この機会にぜひ、ご登録ください！

★★★ 予定されているコンテンツ ★★★
・ライブ配信：新たな花火の楽しみ方として、ドローンによる花火の映像をYouTubeで世界中に発信
・Drive in HANABI：かみふらの宿泊キャンペーンで当日ご宿泊の方は、車に乗車したままま、打ち上がる花火を見ることができます。
・参加型演出：メッセージ花火
・打ち上げ花火：約10分間の花火ですが、上富良野町の夏を感じていただければと思います。
・ライブ配信終了

日 時
令和2年8月29日(土)　19：30～
