update content_bodies set title = 'ベーグル屋さんが作る宿！？✨リアンドベーグルさんプロデュースの宿へ観光協会職員がお邪魔してきました✨ #北広島町 #グルメ', description = '✨リアンドベーグルさんプロデュースの宿へ
観光協会職員がお邪魔してきました✨

「ハルちゃんベーグル焼けたよ～」と呼ばれてレッツらモー‼

アパレルデザインをされていた池田ご夫婦のセンスが施された店内に、ずらりと並んだベーグル達🥯✨
大人買いする気持ちがわかります。全部食べてみたい😋

毎週行列ができるほど人気のベーグルは「むちっふわっ」
自家製酵母で3日間低温長時間発酵で作るベーグルは、酵母の旨味たっぷり！

そんな大人気のベーグル屋さんがこの度新たなプロジェクトを始められました🏠

↓
『一棟貸し宿
FERMELL（ファムル）』

北広島町の自然の美しさや
素敵なお店たち🌿
人々の温かさ、ゆっくりと流れる北広島町…そんな、

＼北広島町の魅力をもっともっと伝えたい！知ってほしい！／

というのが、このプロジェクトの出発点だそう。

🌸本オープンは来年4月ですが
特別に中を見せて頂きました！

洗礼されたおしゃれな空間。細部までこだわりが感じられます。高級ホテルのように品がありながらもホッとするような手作りの温かさがこの宿にはあります🌿

そして一番の注目は「お風呂」
まるで絵画のように神秘的さを引き立てます🖼️

舞太郎くんがすんなり入れる広さで、ご家族で一緒に温まって頂けますよ♪

他にも、3つの寝室に発酵貯蔵庫、ワクワクするようなお部屋がまだまだ沢山あります！
（全貌はまだ内緒☺）

リアンドベーグルさんは宿の完成に向けて「クラウドファンディング」に挑戦中 🚩

詳しくは「キャンプファイヤー　ファムル」「キャンプファイヤー　リアンドベーグル」で検索！

北広島町のハブ(中継地点)となるような
場所を目指し、日々取り組まれている池田ご夫婦の挑戦は続きます。


営業：毎週土曜日のみ
住所：〒731-1712
