update content_bodies set title = 'A Bagel Shop''s Inn!? ✨ We visited the inn produced by Leand Bagel, where the tourism association staff dropped by ✨ #KitahiroshimaTown #Gourmet', description = '✨ We visited the inn produced by Leand Bagel
where the tourism association staff dropped by ✨

"Haruchan, the bagels are ready!" called out, and let''s go‼

Inside, designed with the couple Ikeda''s sense from their apparel design background, rows of bagels are lined up 🥯✨
I understand the feeling of wanting to buy them all. I want to try them all 😋

The popular bagels that have a line every week are "muchi-fuwa"
The bagels made with homemade yeast, fermented at low temperatures for three days, are full of the yeast''s deliciousness!

This popular bagel shop has started a new project 🏠

↓
"Whole House Rental Inn
FERMELL"

The natural beauty of Kitahiroshima Town and
wonderful shops 🌿
The warmth of the people, the slow flow of time in Kitahiroshima Town... such,

＼ We want to convey the charm of Kitahiroshima Town even more! We want you to know! ／

is said to be the starting point of this project.

🌸 The grand opening is in April next year, but
we were specially allowed to see inside!

A sophisticated and stylish space. You can feel the attention to detail. This inn has a handmade warmth that is comforting while being elegant like a luxury hotel 🌿

And the biggest highlight is the "bath"
It enhances the mystique like a painting 🖼️

It''s spacious enough for Maitaro-kun to enter easily, so families can warm up together! 😊

Additionally, there are still many exciting rooms, including three bedrooms and a fermentation storage room!
(The full details are still a secret ☺)

Leand Bagel is currently challenging "crowdfunding" to complete the inn 🚩

For more details, search for "Campfire FERMELL" and "Campfire Leand Bagel"!

The couple Ikeda is working daily towards creating a hub (relay point) in Kitahiroshima Town.

Business Hours: Only on Saturdays
Address: 1828 Toshimi, Kitahiroshima Town, Yamagata District, Hiroshima Prefecture, 731-1712
TEL: 050-5879-7938

Song: Shoun Yamagata "Come on! Kitahiro"

