update content_bodies set title = '安の花田植保存会さんのイベントに招待されました。', description = '★10月11日(日) 
【安の花田植＆壬生の花田植 PRイベント開催しました！】
　　　　～広島市☆イオンモール広島祇園2F～

現在…イオンモール広島祇園2Fの一角で『安の花田植』『壬生の花田植』の風景や様子など、花田植の魅力を伝える写真展を開催しています☆彡　※10/3～10/22まで

『安の花田植』とわがまち北広島町は深いつながりがあり、昨日10月11日(日)に行われた安の花田植保存会主催のイベントにも参加させていただきましたー(^^)/

『壬生の花田植』をはじめとした北広島町の観光PR、また北広島町イメージキャラクター花田舞太郎(もうたろう)が登場し、テーマソング「おいでよ！キタひろ」を可愛い衣装を身につけた采振り(さいふり)のみなさんと踊りました♪

YouTubeを見て、振りを覚えてくれたという子どもたちは、ほぼ完ぺきなダンスで、観客のみなさんを魅了していました(^^♪
本当に素晴らしかったです☆彡

今年は花田植を披露することができませんでしたが、来年の開催に向け、『安の花田植』『壬生の花田植』のPRがしっかりできました！

来年！青空の下、お会いしましょう(^^)/' where id = 'iJOYX3jUJuDAnS5sTZzjj';
update content_bodies set title = 'I was invited to the event of the An no Hanadaue Preservation Society.', description = '★October 11 (Sun) 
[An no Hanadaue & Mibu no Hanadaue PR event was held!] 
～Hiroshima City☆Aeon Mall Hiroshima Gion 2F～

Currently... we are holding a photo exhibition at a corner of Aeon Mall Hiroshima Gion 2F to convey the charm of Hanadaue, showcasing the scenery and atmosphere of ''An no Hanadaue'' and ''Mibu no Hanadaue''☆彡  *From 10/3 to 10/22

''An no Hanadaue'' has a deep connection with our town, Kitahiroshima-cho, and I was able to participate in the event organized by the An no Hanadaue Preservation Society held yesterday, October 11 (Sun)ー(^^)/

The tourism PR of Kitahiroshima-cho, including ''Mibu no Hanadaue'', featured our town''s image character, Hanada Muitaro (Moutarou), who appeared and danced with the performers in cute costumes to the theme song ''Oideyo! Kita Hiro''♪

The children who watched the YouTube video and learned the dance captivated the audience with their nearly perfect performance(^^♪
It was truly wonderful☆彡

This year, we were unable to showcase the Hanadaue, but we were able to effectively promote ''An no Hanadaue'' and ''Mibu no Hanadaue'' in preparation for next year''s event!

Next year! Let''s meet under the blue sky(^^)/' where id = 'dHAkPhnKFd3HCBC28-w9O';
update content_bodies set title = '【北広島町】大朝のテングシデ群落ドローン撮影（2020.5.11）', description = '【国の天然記念物『大朝のテングシデ群落』】
　　　　　～ドローン撮影・映像～
クネクネと曲がりくねったイヌシデの変種が大小約100本群生している『大朝のテングシデ群落』
