update content_bodies set title = '[Kita-Hiroshima Town] Drone Photography of the Tengu Shide Grove in Oasa (2020.5.11)', description = '[National Natural Monument ''Tengu Shide Grove in Oasa'']
～Drone Photography and Video～
The ''Tengu Shide Grove in Oasa'' is home to about 100 twisted and contorted varieties of the Japanese Zelkova tree.
Named after the legend of the Tengu, it has been cherished by the local community.
Designated as a national natural monument, this view can only be seen in Kita-Hiroshima Town in the world☆彡
Please enjoy the beautiful fresh green scenery captured by drone on May 11, a rare video☆彡
[Video Provided by]
Uehiroya Studio, Kita-Hiroshima Town, Hiroshima Prefecture
