update content_bodies set title = '加太活き魚市場', description = '漁師さんが一本釣りで獲った活き魚は、加太蓄養施設に運ばれ各地に流通していきます。
加太産、一本釣り、活きているということで阪神地域では高値で取引されています。

都会では高額ですが、加太で食べればお手頃価格。
魚の本当の美味しさを確かめにいらっしゃいませんか？
一般の方にも販売するイベントもございますので、お問合せください。' where id = '9Hg25BYE2_0-RqlWxu9Xn';
update content_bodies set title = 'Kada Live Fish Market', description = 'The live fish caught by fishermen using pole-and-line fishing are transported to the Kada aquaculture facility and distributed to various regions.
Due to being locally sourced, pole-and-line caught, and alive, they are traded at high prices in the Hanshin area.

While they are expensive in the city, they are reasonably priced when eaten in Kada.
Why not come and experience the true deliciousness of the fish?
We also have events where we sell to the general public, so please contact us.' where id = '6B0dHXShSIXgqQJRZVpbb';
update content_bodies set title = 'グレ（メジナ）の調理', description = '一本釣りで獲ったグレの調理です。
活きているグレを締めた鮮度の良さは、街で味わうことはできません。
グレってこんなに美味しい魚だったんだと皆さん驚かれます。
加太観光協会青年部長 稲野雅則氏（活き魚料理いなさ）の美技をごらんください。' where id = 'ccJMPoiu2_eZS7JpIuJvH';
update content_bodies set title = 'Cooking Gray (Mejina)', description = 'This is the cooking of gray caught by single-line fishing.
The freshness of a live gray that has been dispatched cannot be experienced in the city.
Everyone is surprised to find out how delicious gray is.
Please take a look at the exquisite skills of Mr. Masanori Inano, the head of the Kadota Tourism Association Youth Division (Ikizukuri Ryori Inasa).' where id = 'vNoBLyrEhicQXZjvEPqDT';
update content_bodies set title = '一本釣りアジの調理', description = '紀淡海峡の速い潮で育った天然一本釣りのアジです。
網で獲ったアジとはまったく別物の味！
直前まで活きていた鮮度バツグンの逸品です。
加太観光協会青年部長 稲野雅則氏（活き魚料理いなさ）の美技をごらんください。' where id = 'KZrfwPIemzTAvkTrSacS2';
update content_bodies set title = 'Cooking Wild-Caught Horse Mackerel', description = 'This is a naturally caught horse mackerel, raised in the fast currents of the Kitan Strait.
It has a completely different taste from those caught with nets!
This is a superb product with outstanding freshness, having been alive until just before preparation.
Please enjoy the exquisite skills of Mr. Masanori Inano, the head of the Youth Division of the Kada Tourism Association (Ikizukuri Restaurant Inasa).' where id = 'RjKaSmeXiv-OnBsN4r56n';
update content_bodies set title = '乗船注意ビデオ', description = '本物の一本釣り漁船に乗ります！
海が相手ですので、乗船前にこのビデオでちょっと勉強していただきます。
出演は虹色ポッケさんです。

観光船ではない男の戦場！お客様用の座席もありません。
でもめったに経験することのできない貴重な体験になります。
加太観光協会では定期的に漁船乗船・一本釣り体験ツアーなどを開催していますので、お問合せください。' where id = 'vasG29jBIibPsOfegL2HI';
update content_bodies set title = 'Boarding Safety Video', description = 'You will board a real longline fishing boat!
Since the sea is our opponent, please take a moment to study this video before boarding.
Featuring Nijiiro Pokke.

This is a man''s battlefield, not a sightseeing boat! There are no seats for customers.
But it will be a rare experience that you won''t often have.
The Kada Tourism Association regularly holds fishing boat boarding and longline fishing experience tours, so please contact us.' where id = 'khSdQApCOL6wrnHrvdL9I';
update content_bodies set title = '【兵庫県】日本遺産　西国巡礼二十五番札所　播州清水寺【加東市】', description = '播州清水寺は兵庫県加東市の御嶽山山頂に立ち、地蔵信仰の聖地として今昔物語集にも登場します。日本遺産・西国三十三所巡礼の第２５番札所とされる当寺の大講堂は古くから沢山の方が巡礼に訪れます。

また花や新緑、紅葉の美しい４月～１１月のシーズンは多くの方々が観光に訪れます。' where id = '8viq1dQ2VOP8s1JjdSha6';
update content_bodies set title = '[Hyogo Prefecture] Japan Heritage - 25th Sacred Site of the Saigoku Pilgrimage - Banshu Seiz temple [Kato City]', description = 'Banshu Seiz temple stands at the summit of Mount Ontake in Kato City, Hyogo Prefecture, and is mentioned in the Konjaku Monogatari as a sacred site of Jizo faith. This temple, recognized as the 25th sacred site of the Japan Heritage Saigoku 33 Pilgrimage, has long attracted many pilgrims to its grand lecture hall.

Additionally, from April to November, during the beautiful seasons of flowers, fresh greenery, and autumn leaves, many visitors come for sightseeing.' where id = 'yXo6xh1aGcRC6vgytsbAN';
