update content_bodies set title = '神戸の旅 HD', description = '神戸の旅
●http://www.feel-kobe.jp/
都市の観光魅力はどこに宿っているのでしょうか。
人は何を求めて旅をするのでしょうか。

普段と違う体験、日常から離れた刺激や安らぎ、そして、自らを高めていく何物か。
そのようなものを求めて、人は旅をするのではないでしょうか。

この旅の目的を、歴史遺産の中に観るのか、それとも、時の流れの中で、変化してきた「その都市の今」の中に感じるのか。それは旅人の選択の中にあります。
  
それは旅人の選択の中にあります。

この映像は、変化する時代の中で培われてきた神戸の美意識や生活スタイルを、3分半に凝縮しています。神戸の今を感じてください。' where id = 'qd8A3qqJzWEMOfGkKKdsq';
