update content_bodies set title = '【予告】ＶＲ松山城～謎の姫と幻の合戦～【68秒Ver.】', description = '令和3年7月1日に松山城天守内にVR体験コーナーが新登場！360度カメラやCGなどの技術を駆使した臨場感あふれる映像で、普段見ることのできない松山城の姿をお楽しみください。ナレーションは、愛媛県出身の声優・水樹奈々さんが担当。圧倒的な演技力で、体験者を不思議なストーリーへといざないます。' where id = 'h2Y9mJ_oL66vVUd7qdEf5';
update content_bodies set title = '[Preview] VR Matsuyama Castle - The Mysterious Princess and the Phantom Battle - [68 seconds Ver.]', description = 'On July 1, 2021, a new VR experience corner will be unveiled inside the Matsuyama Castle keep! Enjoy the captivating visuals of Matsuyama Castle, which you usually cannot see, using cutting-edge technologies such as 360-degree cameras and CGI. The narration will be provided by Nana Mizuki, a voice actress from Ehime Prefecture. With her overwhelming acting skills, she will guide participants into a mysterious story.' where id = 'KRkZVEztbODrd_Nw0Toki';
update content_bodies set title = '【予告】ＶＲ松山城～謎の姫と幻の合戦～【40秒Ver.】', description = '令和3年7月1日に松山城天守内にVR体験コーナーが新登場！360度カメラやCGなどの技術を駆使した臨場感あふれる映像で、普段見ることのできない松山城の姿をお楽しみください。ナレーションは、愛媛県出身の声優・水樹奈々さんが担当。圧倒的な演技力で、体験者を不思議なストーリーへといざないます。' where id = 'EoRGVNENX5HRne7SbZvQF';
update content_bodies set title = '[Preview] VR Matsuyama Castle - The Mysterious Princess and the Phantom Battle - [40 sec Ver.]', description = 'On July 1, 2021, a new VR experience corner will be unveiled inside the Matsuyama Castle keep! Enjoy the captivating visuals of Matsuyama Castle, which you usually cannot see, using cutting-edge technologies like 360-degree cameras and CGI. The narration will be provided by Nana Mizuki, a voice actress from Ehime Prefecture. With her overwhelming acting skills, she will guide participants into a mysterious story.' where id = 'e54XwTRoU3JPwpp-1V_Ot';
