update content_bodies set title = '[Preview] VR Matsuyama Castle - The Mysterious Princess and the Phantom Battle - [15-second Ver.]', description = 'On July 1, 2021, a new VR experience corner will open inside the Matsuyama Castle keep! Enjoy the breathtaking visuals of Matsuyama Castle, which you usually cannot see, using cutting-edge technologies like 360-degree cameras and CGI. The narration will be provided by Nana Mizuki, a voice actress from Ehime Prefecture. With her overwhelming acting skills, she will guide participants into a mysterious story.' where id = 'UDjLfQV47a3M3Ehefy8qi';
update content_bodies set title = '金魚ねぷたの作り方', description = '弘前ねぷたは1722(享保7)年に初めて文献に登場してから、2022(令和4)年に300年という節目を迎えました。
　弘前ねぷた300年祭実行委員会では、弘前ねぷたの歴史と伝統の継承、そして未来へ繋げるため、『金魚ねぷたの作り方』動画を制作しました。

弘前ねぷたまつり
https://www.hirosaki-kanko.or.jp/edit.html?id=cat02_summer_neputa

弘前ねぷた300年祭
https://www.hirosaki-kanko.or.jp/edit.html?id=neputa300

弘前ねぷた300年祭実行委員会
（弘前市観光部観光課内）
TEL：0172-40-0236' where id = 'yJXBad6aqpEs-WnHGFVab';
update content_bodies set title = 'How to Make Goldfish Neputa', description = 'Hirosaki Neputa first appeared in literature in 1722 (the 7th year of the Kyoho era) and celebrated its 300th anniversary in 2022 (the 4th year of the Reiwa era).
The Hirosaki Neputa 300th Anniversary Executive Committee has produced a video titled ''How to Make Goldfish Neputa'' to inherit the history and traditions of Hirosaki Neputa and connect them to the future.

Hirosaki Neputa Festival
https://www.hirosaki-kanko.or.jp/edit.html?id=cat02_summer_neputa

Hirosaki Neputa 300th Anniversary
https://www.hirosaki-kanko.or.jp/edit.html?id=neputa300

Hirosaki Neputa 300th Anniversary Executive Committee
(Within the Hirosaki City Tourism Department)
TEL: 0172-40-0236' where id = 'HMeUp6dpySbUwBh1-Jge6';
update content_bodies set title = '【松山市公式PR動画】 道後温泉歓迎楽団「桶ストラ」', description = '松山市公式観光PR動画「桶ストラ」
https://matsuyama-sightseeing.com/

道後温泉を舞台に管弦楽団による雄大な​ウィンナ・ワルツの調べと 温泉特有の「コーン」という「桶」の音の ほっこり感をミックスさせ、歓迎楽団で、観光客をお迎えする気持ちを“オーケストラ”風に表しました。

松山市 産業経済部 観光・国際交流課
〒790-8571 愛媛県松山市二番町4丁目7番地2
TEL 089-948-6556 （受付時間：月〜金 8:30〜17:15）' where id = 'Z3m8poeTaC8MGlx6Py8M9';
update content_bodies set title = '[Matsuyama City Official PR Video] Dogo Onsen Welcome Orchestra ''Oke Sutra''', description = 'Matsuyama City''s official tourism PR video ''Oke Sutra'' https://matsuyama-sightseeing.com/

Set against the backdrop of Dogo Onsen, the grand melodies of a Viennese waltz performed by an orchestra are mixed with the warm sounds of the ''桶'' (oke) unique to the hot springs, creating a welcoming atmosphere for tourists in an ''orchestra'' style.

Matsuyama City, Department of Industry and Economy, Tourism and International Exchange Division
790-8571 2-7-2 Nibancho, Matsuyama City, Ehime Prefecture
TEL 089-948-6556 (Reception hours: Mon-Fri 8:30-17:15)' where id = 'S0m8crcbGMVWKeMGKEj5s';
update content_bodies set title = 'アップルブランデーの向こうの郷 ～醸成していく弘前旅～　イメージショートムービー', description = '弘前大学の学生が考案した、より豊かな文化体験を求めるプレミアム世代をターゲットとしたアート・ツアー。その名も「アップルブランデーの向こうの景色　醸成してゆく弘前旅」。県外からやってくる大人の観光客を想定して学生たちが提案したツアーのイメージショートムービーです。' where id = 'CL9tONPVLuPCxOGwq5LoM';
update content_bodies set title = 'Beyond Apple Brandy: A Journey of Cultivation in Hirosaki - Image Short Movie', description = 'An art tour targeting the premium generation seeking richer cultural experiences, conceived by students of Hirosaki University. The tour is named ''The Scenery Beyond Apple Brandy: A Journey of Cultivation in Hirosaki.'' This is an image short movie proposed by students, envisioning adult tourists coming from outside the prefecture.' where id = 'eSFLJ1CT_tiOSL3QGl4er';
update content_bodies set title = 'HIROHAKO: Seasonal Adventure with Snow Miku & Sakura Miku【ひろはこ】', description = '"Hirohako" signifies the cooperation between Hirosaki City and Hakodate City, referencing the name of both cities.

