update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11.1〜11.7に弘前公園では、
「弘前城 菊と紅葉まつり」が開催されています。
「弘前城 菊と紅葉まつり」（通称 菊もみ）に弘前大学の学生がリポーターとなり、潜入取材を敢行！
フラワーアートの制作風景や、まつりの楽しみ方などをお届けします。

 今回は、「青龍を見つけよう！」を動画でご紹介します！

植物園内の様々なところに、雪吊り飾りの「青龍」たちは、９体ひそんでいます。青龍とは、慶び事や発展を促すとも言われている縁起のよい守り神です。園内に潜む九体の青龍を見つけると、いいことが起きるかも…！？

ちなみの動画内では、３体の青龍が映り込んでいます。
おわかりいただけたでしょうか……？

https://www.hirosaki-kanko.or.jp/flowerart/' where id = 'SKC-VfVHDe4bsR5GXWk7o';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" is being held at Hirosaki Park.
Students from Hirosaki University are acting as reporters and conducting undercover coverage of the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" (commonly known as Kiku Momi)!
We will deliver scenes of flower art production and ways to enjoy the festival.

This time, we will introduce "Let''s Find the Seiryu!" in a video!

In various places within the botanical garden, there are nine hidden "Seiryu" decorations with snow hanging. The Seiryu is said to be a lucky guardian deity that promotes joy and development. If you find the nine Seiryu lurking in the garden, something good might happen...!?

By the way, three Seiryu appear in the video.
Did you catch them...?

https://www.hirosaki-kanko.or.jp/flowerart/' where id = 'BK3eYhMcNJ-t3n5ZJVoiY';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11.1〜11.7に弘前公園では、
「弘前城 菊と紅葉まつり」が開催されています。
「弘前城 菊と紅葉まつり」（通称 菊もみ）に弘前大学の学生がリポーターとなり、潜入取材を敢行！
フラワーアートの制作風景や、まつりの楽しみ方などをお届けします。

 今回は学生記者クラブおすすめの巡り方を動画でご紹介します！

フラワーアートのコンセプトに合わせて、東門から入場するルートです。

祭り期間も終盤になってまいりました。
休日はクラフトマーケットも開催され、混雑する時間帯もあるかもしれません。

ゆったり見たい方は、開園すぐが狙い目です。

https://www.hirosaki-kanko.or.jp/flowerart/' where id = 'SFPuNxVAp7pJPAagjGiKC';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" is being held at Hirosaki Park.

Students from Hirosaki University are acting as reporters for the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" (commonly known as Kiku Momi) and conducting undercover coverage!
We will deliver scenes of flower art production and ways to enjoy the festival.

This time, we will introduce a recommended route by the Student Reporter Club in a video!

This route enters through the East Gate, in line with the concept of flower art.

The festival period is now in its final stages.
On holidays, a craft market is also held, so there may be busy times.

For those who want to take their time, the best time to visit is right when the park opens.

https://www.hirosaki-kanko.or.jp/flowerart/' where id = '8C9-MTfNluHFv3dauCMrC';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11.1〜11.7に弘前公園では、
「弘前城 菊と紅葉まつり」が開催されています。
「弘前城 菊と紅葉まつり」（通称 菊もみ）に弘前大学の学生がリポーターとなり、潜入取材を敢行！
フラワーアートの制作風景や、まつりの楽しみ方などをお届けします。

 もうすでに、ご来場いただいた方もいらっしゃるでしょうか？
遅ればせながら今回は、より深くフラワーアートを愉しむための鑑賞順序についてお届けします。

東からやってきた龍は、東門を通り、弘前城植物園に入ってきました。
花くぐりを通り抜け、龍は白い花を頭につけたまま三の丸庭園に鎮座しています。
花手水は、龍の足跡を表現します。

龍の横にそびえるりんごの木には、願いがこもった赤い実がつきます。
りんごの木から追手門に向かう花手水は、木から飛んだりんごの葉が溢れ、三の丸庭園の追手門側には大きなりんごが実を結んでいます。

物語のようになってしまいましたが、

弘前城植物園東門入り口
　↓
花くぐり
　↓
花手水
　↓
昇天華龍
　↓
りんごのウィッシュツリー
　↓
追手門側へ

というようにフラワーアート「枯木龍吟」の物語が進みます。
物語を知った上での鑑賞はより深く、感じ入るものがあります。

https://www.hirosaki-kanko.or.jp/flowerart/' where id = 'Rh6AWV0SSV23vpKKoMzJI';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" is being held at Hirosaki Park.
Students from Hirosaki University are acting as reporters and conducting undercover coverage of the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" (commonly known as Kiku Momi)!
We will deliver scenes of flower art production and ways to enjoy the festival.

Have some of you already visited?
Belatedly, this time we will present the order of appreciation for enjoying flower art more deeply.

The dragon that came from the east passed through the East Gate and entered the Hirosaki Castle Botanical Garden.
Passing through the flower arch, the dragon is seated in the San-no-Maru Garden with white flowers on its head.
The flower water represents the dragon''s footprints.

Next to the dragon, the apple tree towers, bearing red fruits filled with wishes.
The flower water leading from the apple tree to the Otemon Gate overflows with apple leaves that have fallen from the tree, and a large apple is bearing fruit on the Otemon side of the San-no-Maru Garden.

It has turned into a story, but,

Hirosaki Castle Botanical Garden East Gate Entrance
　↓
Flower Arch
　↓
Flower Water
　↓
Ascended Flower Dragon
　↓
Apple Wish Tree
　↓
Towards Otemon

Thus, the story of the flower art "Kareki Ryugin" progresses.
Appreciating the story adds depth and resonance to the experience.

https://www.hirosaki-kanko.or.jp/flowerart/' where id = 'iWzFSkGSCF2f_xyrdCW23';
update content_bodies set title = '＼旬感！ 菊もみ！ 学生記者クラブ／', description = '11.1〜11.7に弘前公園では、
「弘前城 菊と紅葉まつり」が開催されています。
「弘前城 菊と紅葉まつり」（通称 菊もみ）に弘前大学の学生がリポーターとなり、潜入取材を敢行！
フラワーアートの制作風景や、まつりの楽しみ方などをお届けします。

 今回は白い花で飾りつけられた、花くぐりの制作風景を動画でお届けします。

大人でも楽々通り抜けられる大きさの花くぐり。
白い花はアーティフィシャルフラワーという精巧に作られた造花です。
写真映え間違いなしのフラワーアートとなっております。

通り抜けるだけで、澄んだ気持ちになります。
アーティフィシャルフラワーに近づいてみて、どれだけ精巧かとくとご覧ください！

https://www.hirosaki-kanko.or.jp/flowerart/' where id = '_eYH6Vl0DxDMRoEHYOzYo';
update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the Hirosaki Park is hosting the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival." 
During the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" (commonly known as Kiku Momi), students from Hirosaki University will act as reporters and conduct undercover coverage! 
We will deliver scenes of flower art production and ways to enjoy the festival.

This time, we present a video of the production scene of the flower arch decorated with white flowers.

The flower arch is large enough for adults to easily pass through. 
The white flowers are artificial flowers, intricately crafted. 
It is a flower art that is sure to look great in photos.

Just passing through brings a sense of clarity. 
Come closer to the artificial flowers and see how intricate they are!

