update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" is being held at Hirosaki Park.

Students from Hirosaki University are acting as reporters and conducting undercover coverage of the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" (commonly known as Kiku Momi)!
We will deliver scenes of flower art production and ways to enjoy the festival.

This time, we will present a video of the lighting up within the venue!

When illuminated, the red of the autumn leaves stands out more against the dark background.

The soaring dragon, when viewed during the day, showcases the intricacy of the arrangement and the vibrancy of the flowers, but the spectrum illuminating the dragon at night, combined with the instrumental music, strangely elevates the mood.
It is screened daily from 17:00 to 18:45 during the festival period.

Please be careful as the ground is also dark!

