update content_bodies set title = 'Seasonal Sensation! Kiku Momi! Student Reporter Club', description = 'From November 1 to November 7, the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" will be held at Hirosaki Park.

Students from Hirosaki University will act as reporters and conduct undercover coverage of the "Hirosaki Castle Chrysanthemum and Autumn Leaves Festival" (commonly known as Kiku Momi)!
We will deliver scenes of flower art production and ways to enjoy the festival.

The highlight of this year''s flower art, the head of the Ascending Dragon, has arrived at the San-no-Maru Garden. The body is 100 meters long, and the head is impressive in size.

As you get closer, you will be amazed by the intricacy of the sculpture. This dragon will be adorned with flowers.
It will become a vibrant work that gives energy to those who see it.

Projection mapping will also be available to show soon.' where id = 'H80pp54HawgUhTsy88-cG';
