update content_bodies set title = '予期せぬ出会い～Unexpected Encounter～', description = '作品名：「予期せぬ出会い～Unexpected Encounter～」　

監督―― 宮田 耕輔
映像――反保シュウジ
写真――Eito Mars

撮影場所：
ウドノスビーチ・寺崎漁港・鳩の池・大金久海岸・サトウキビ畑・アジニッチェー神社・味咲・居酒屋やす　など

撮影秘話：
人に会いに行く島。
　宮田組一行は、3泊4日のスケジュールで初日の午後与論島に到着し、ゲストハウスKAIを拠点に撮影場所は実際に島を巡りながら、人の温かさに触れる旅を想定した企画を元に、「与論の人に出会う旅の中で、物書きの宮田氏が与論で感じ綴られた言葉と、Eito Mars氏が切り取った与論島の美しい情景、その旅の様子とまた別の視線で捉えた反保氏の映像がMIXされて作り出される観光映像」を制作するという内容で撮影を進めていきました。
　宮田組はレンタカーで島を巡りながら、ウドノスビーチで与論島産みずレモンを栽培している島人から、観光客があまり知らない夕日スポットを教えてもらって撮影したり、粂田監督の撮影にも協力を頂いていた肥田みちよさんが行っているテントサウナを体験したり、朝日のシーンを撮影に訪れた鳩の池では、三線と法螺貝で観光客をもてなす島人に出会うなど、与論の人の出会いが繋がりながら、撮影がすすめられました。その島の人との出会いの体験を元に、実際に宮田監督が紡いだ文章が作品内で使用されるテロップに流れ、その心象風景を納めたスチールカメラの写真と実写が映し出される映像作品として仕上がりました。' where id = '8OOdjo_3OXrxbosYJ6VRV';
update content_bodies set title = 'Unexpected Encounter', description = 'Title: "Unexpected Encounter"  

Director: Kousuke Miyata  
Cinematography: Shuji Hanbo  
Photography: Eito Mars  

Filming Locations:  
Udono Beach, Terasaki Fishing Port, Pigeon Pond, Okaneku Coast, Sugarcane Fields, Ajinichie Shrine, Ajisaki, Izakaya Yasu, etc.  

Filming Anecdote:  
A journey to meet the people of the island.  
The Miyata crew arrived on Yoron Island on the afternoon of the first day with a 3-night, 4-day schedule, using Guest House KAI as a base. The filming locations were planned to be a journey that would allow them to experience the warmth of the island''s people while actually touring the island. The project aimed to create a tourism video that mixes the words written by writer Miyata, who felt and recorded his experiences on Yoron, the beautiful scenery of Yoron Island captured by Eito Mars, and the footage taken by Shuji Hanbo from a different perspective during the journey.  
The Miyata crew traveled around the island by rental car, filming at Udono Beach where they learned about a sunset spot that tourists rarely know from a local who cultivates Yoron Island''s water lemons. They also experienced a tent sauna run by Michiyo Hida, who had been assisting Director Kumeda with filming. At Pigeon Pond, where they visited to capture the sunrise scene, they encountered locals who welcomed tourists with the sanshin and conch shell. The filming progressed as connections with the people of Yoron were made. Based on the experiences of meeting the island''s people, the text woven by Director Miyata was used in the subtitles of the work, culminating in a video piece that showcased both still photographs capturing the mental landscape and live-action footage.' where id = 'HmTO06trpvyxXLofTZBBU';
update content_bodies set title = '【ヨロン島 | YORON Island】注意してほしい5つのポイント | FIVE THINGS TO KEEP IN MIND', description = 'ヨロン島公式サイト：https://www.yorontou.info/
ヨロン島公式インスタグラム：https://www.instagram.com/yoron_island_official/?hl=ja

「ヨロンブルー」と呼ばれる美しい海に囲まれたヨロン島。
サンゴ礁に囲まれた小さな島は、海にはウミガメやカラフルな魚たちが戯れ、島のあちこちでハイビスカスやブーゲンビリアが咲き誇る南国の楽園です。
この動画ではヨロン島に訪れる前にお伝えしておきたい「注意してほしい5つのポイント」をまとめた動画です。

もしかしたらちょっと不便に感じることも、ヨロンの旅の醍醐味です。
いつもとは違う島時間。美しい自然や、優しい人たちとの出会いは、忘れられない想い出になりますよ。

備えあれば、想い出いっぱい

是非、こちらの動画を見てから、ヨロン島の旅をお楽しみください。

