update content_bodies set title = '【ヨロン島】沖縄からヨロン島へのフェリーの旅（Travel 編）', description = '公式サイト：http://www.yorontou.info/
公式インスタグラム：https://www.instagram.com/yoron_island_official/

沖縄北部エリアは2021年に世界自然遺産に認定されました。
沖縄北部のやんばるの森には、美しく生い茂る緑豊かな森や、清らかな水の流れ、数多くの希少な動植物が生息します。

沖縄北部の本部港からフェリーで約2時間、美しい青い海を誇る「南国の楽園 ヨロン島」があります。

ヨロン島には美しく青く輝くYORON BLUEの海、そしてそれを楽しむ様々なマリンレジャーがあります。
また、海だけでなく、歴史や郷土文化、美味しい食事、そして島の人々との出会いが忘れられない旅の思い出を作ります。
友達と一緒に、カップルでも、ファミリーでも、この島の美しい海と優しい人々は、いつでもあなたを待っています。

沖縄のやんばるの緑と、ヨロン島の美しい海のブルー。
海を挟んで広がる異なる2つの魅力はフェリーで繋がり、1つの特別な観光体験をお届けします。

---

Created by 81plus : https://81plus.jp/' where id = 'AJe4QfWs5qCClqaRyy0LP';
update content_bodies set title = '[Yoron Island] A Ferry Journey from Okinawa to Yoron Island (Travel Edition)', description = 'Official website: http://www.yorontou.info/
Official Instagram: https://www.instagram.com/yoron_island_official/

The northern area of Okinawa was designated as a UNESCO World Heritage Site in 2021.
In the forests of Yanbaru in northern Okinawa, there are lush green forests, clear flowing waters, and numerous rare plants and animals.

About 2 hours by ferry from Motobu Port in northern Okinawa lies Yoron Island, a ''tropical paradise'' boasting beautiful blue seas.

Yoron Island features the stunning YORON BLUE sea and various marine leisure activities to enjoy.
Moreover, not only the sea, but also history, local culture, delicious food, and encounters with the island''s people create unforgettable travel memories.
Whether with friends, as a couple, or with family, the beautiful sea and kind people of this island are always waiting for you.

The greenery of Yanbaru in Okinawa and the beautiful blue sea of Yoron Island.
These two different attractions, separated by the sea, are connected by a ferry, delivering a unique tourism experience.

---

Created by 81plus: https://81plus.jp/' where id = 'bNBLFnZK9STyMe_dVR9l6';
update content_bodies set title = '日日是与論 4K  Yoron Island,Nature moves on,as do we', description = 'Learn more about Yoron Island
https://travel.yorontou.info/

　タイトルの「日日是与論＝にちにちこれよろん」は、禅語である「日日是好日（その日一日に感謝し、ただありのままに生きる」をオマージュしたもの。2020年、コロナを経験した私たちはいま、「日常」こそが有難く「特別」な時間の重なりであることを知りました。
　「与論島」は、観光の島であるという観点から、コロナ禍でのダメージはもちろん大きなことですが、それは世界中どこでも同じこと。それどころか毎年の台風をはじめとする自然災害や戦争も乗り越えてきた島です。
　今回のART&FACTORY JAPAN出品作では、与論島に暮らすさまざまな「いのち」の擬人化を通して、大きな自然のサイクルを受け入れながら日々を繰りかえす、島の美しさやたくましさを表現します（とはいえ、与論の日常はほかの街に住む人からみれば大いなる非日常ですが）。
　与論島から、同じような問題を抱え悩む離島や、過疎の町、”今”を生きるすべての人たちへのエールとなるように。

監督：楠健太郎
撮影：楠健太郎。邉見知晃、松田昌樹
編集：楠健太郎
題字：東學
音楽：渡邊崇
詩　：村上美香
英題：藤井智絵美
語り：西原未紗
録音：邉見知晃
整音：出原亮' where id = 'zxBQkP81Tct8xHMnRm_Wo';
update content_bodies set title = 'Every Day is Yoron 4K Yoron Island, Nature moves on, as do we', description = 'Learn more about Yoron Island
https://travel.yorontou.info/

The title "日日是与論＝にちにちこれよろん" is an homage to the Zen phrase "日日是好日 (Be grateful for each day and live as it is)." In 2020, after experiencing the pandemic, we learned that our "daily life" is indeed a precious overlap of "special" moments.

From the perspective of being a tourist island, Yoron Island has certainly suffered significant damage due to the pandemic, but this is true everywhere in the world. Moreover, it is an island that has overcome natural disasters such as annual typhoons and wars.

In this work presented at ART&FACTORY JAPAN, we express the beauty and resilience of the island through the personification of various "lives" that inhabit Yoron Island, while accepting the great cycles of nature that repeat day by day (though, to those living in other cities, daily life in Yoron may seem like a great non-daily experience).

From Yoron Island, we hope to send a message of encouragement to other remote islands and depopulated towns facing similar issues, as well as to all people living in the "now."

Director: Kentaro Kusunoki
Cinematography: Kentaro Kusunoki, Akihiro Bemimi, Masaki Matsuda
Editing: Kentaro Kusunoki
Title Design: Gaku Higashi
Music: Takashi Watanabe
Poetry: Mika Murakami
English Title: Chiemi Fujii
Narration: Misa Nishihara
Sound Recording: Akihiro Bemimi
Sound Editing: Ryo Idehara' where id = '3f7BO3icPnI3PtoUNZ0mi';
