update content_bodies set title = '南阿蘇のやさしい氷2023【キャンペーン第2弾】', description = '【🍧夏の風物詩「南阿蘇のやさしい氷プロジェクト2023」第2弾🍧】
梅雨明け間近で夏休みも始まりこれから夏本番ですね！
7月15日（土）から始まった第１弾の南阿蘇かき氷キャンペーンに続き、
第２弾が7月22日（土）からスタートします。
今年もかき氷のオリジナルグッズ満載ですよ！
南阿蘇でかき氷を食べてグッズをゲットしよう！
第2弾の内容はこちら！
①「南阿蘇かき氷部　入部キャンペーン」
ついに配布開始となる「かき氷マップ2023」の裏面が、なんとかき氷部の入部届に！？
今年はあなたも南阿蘇かき氷部に入部して「南阿蘇のやさしい氷」を応援しよう！
かき氷を食べて、店舗でスタンプをもらってオリジナルリストバンドを手入しよう！
②南阿蘇観光案内所で限定ガチャ（1回500円）を回してオリジナルグッズを入手しよう！
キーホルダー・マスキングテープ・手拭い・Tシャツ・ビブス・バケットハットの期間限定氷グッズが当たりますよ！稀にかき氷無料券が入っているかも！？
（※かき氷マップは７月２２日から掲載店舗や観光案内所などで配布開始いたします。マップデータは７月１５日より下記のリンクからご確認いただけます。）�https://minamiaso.info/blog/kakigori2023/
