update content_bodies set title = 'Gentle Ice of Minami Aso 2023 [Campaign Part 2]', description = '[🍧 Summer Tradition "Gentle Ice Project of Minami Aso 2023" Part 2 🍧]
The rainy season is almost over, and summer vacation is starting, so summer is just around the corner!
Following the first part of the Minami Aso shaved ice campaign that started on July 15 (Saturday),
the second part will start on July 22 (Saturday).
This year, we have plenty of original shaved ice merchandise!
Come enjoy shaved ice in Minami Aso and get some goodies!
Here are the details of Part 2!
① "Minami Aso Shaved Ice Club Membership Campaign"
Finally, the distribution of the "Shaved Ice Map 2023" will begin, and the back side will somehow be the membership application for the Shaved Ice Club!?
This year, you can also join the Minami Aso Shaved Ice Club and support "Gentle Ice of Minami Aso"!
Eat shaved ice, get a stamp at the store, and receive an original wristband!
② Spin the limited gacha (500 yen per spin) at the Minami Aso Tourist Information Center to get original goods!
You can win limited-time ice goods like keychains, masking tape, hand towels, T-shirts, vests, and bucket hats! Occasionally, you might even find a free shaved ice coupon inside!?
(*The shaved ice map will be distributed starting July 22 at participating stores and tourist information centers. You can check the map data from the link below starting July 15.)
https://minamiaso.info/blog/kakigori2023/
---------------------------------------------------
<① Overview of the Minami Aso Shaved Ice Club Membership Campaign>
■ Duration: July 22 (Saturday) – August 31 (Thursday)
■ Location: All 10 stores listed on the shaved ice map
■ Distribution: Shaved ice map (with the membership application on the back) and wristband
■ Exchange location: Activity Center Minami Aso
■ Steps are as follows:
↓↓↓↓↓
・Eat shaved ice at a participating store
・Get a stamp in the membership application section on the back of the shaved ice map
・Submit the membership application at the "Activity Center Minami Aso" inside the Roadside Station Aso Nozomi no Sato Kugino
・Receive your wristband
*You can receive one stamp per person for each shaved ice purchased. (You can also stamp for your companions)
*Only one membership application per person is allowed.
<② Overview of the Limited Gacha>
■ Sales period: July 22 (Saturday) – until sold out
■ Sales location: Minami Aso Tourist Information Center
■ Price: 500 yen per spin
<Shaved Ice Providing Stores>
(Please check the operating status of each store directly on the day.)
・Berry Tree Berry
・Kyunaga-ya
・Manpuku Goya Donburako
・Thai Cuisine Aroi Jan
・Ichigo Rinka
・Furyu Kazaru Café
・Tenohan an
・Minami Aso Confectionery Suisui
・Kino Uchi Farm
・Ironaki Kaze
■ Inquiries
Activity Center Minami Aso (Roadside Station Aso Nozomi no Sato Kugino)
Address: 2807 Kushi, Minami Aso Village, Aso District, Kumamoto Prefecture
Business hours: 9:00 AM – 5:00 PM
TEL: 0967-67-2222 (Minami Aso Tourist Information Center)
■ For more details, click here
https://minamiaso.info/blog/kakigori2023/

