update content_bodies set title = '南阿蘇のやさしい氷2023【キャンペーン第1弾】', description = '【🍧夏の風物詩「南阿蘇のやさしい氷プロジェクト2023」第1弾🍧】

本日7月15日（土）に南阿蘇鉄道全線開通や熊本地震震災ミュージアム体験・展示施設の「KIOKU」がオープンすることもあり今年の夏は今まで以上に注目の南阿蘇です。

2019年に始まり、今年で5年目を迎える夏の風物詩となった夏期イベントの「南阿蘇のやさしい氷プロジェクト」が始動。今年は、第1弾・第2弾の2部構成！
まずは７月１５日（土）より第1弾「おかえり！南阿蘇鉄道キャンペーン」がスタートします！
対象店舗でかき氷を食べた方に南阿蘇鉄道とコラボした限定の「南阿蘇鉄道全線再開記念コースター」をプレゼントいたします！
こちらは、数量限定で無くなり次第終了になりますのでお早めに！
（※７月１５日より順次配布開始いたします。配布開始期間は店舗によって異なりますので予めご了承ください。）

続く第2弾は７月２２日（土）スタート！
今年もかき氷マップを配布します！南阿蘇で素材にこだわって作られた、『南阿蘇のやさしい氷』はどれも絶品！今年は、掲載店舗が昨年の9店舗から更に1店舗増えて、合計10店舗に！
もちろん第2弾はこれだけではありません！気になる詳細は近日公開！
（※かき氷マップは７月２２日から掲載店舗や観光案内所などで配布開始いたします。マップデータは７月１５日より下記のリンクからご確認いただけます。）
https://minamiaso.info/blog/kakigori2023/

暑い日には、各店舗の自信作かき氷を食べに南阿蘇へクールダウンしに来ませんか？
皆さまのお越しをお待ちしております。
---------------------------------------------------
