update content_bodies set title = 'Gentle Ice of Minami Aso 2023 [Campaign Part 1]', description = '【🍧Summer Tradition "Gentle Ice Project of Minami Aso 2023" Part 1🍧】

Today, July 15th (Saturday), marks the full reopening of the Minami Aso Railway and the opening of the "KIOKU" experience and exhibition facility at the Kumamoto Earthquake Disaster Museum, making this summer more noteworthy than ever for Minami Aso.

Starting in 2019, the summer event "Gentle Ice Project of Minami Aso" has become a summer tradition, now entering its fifth year. This year, it will be divided into two parts: Part 1 and Part 2!
First, starting from July 15th (Saturday), Part 1, the "Welcome Back! Minami Aso Railway Campaign" will kick off!
Those who enjoy shaved ice at participating stores will receive a limited edition "Minami Aso Railway Full Line Reopening Commemorative Coaster" in collaboration with the Minami Aso Railway!
This is available in limited quantities and will end as soon as they run out, so be sure to get yours early!
(*Distribution will begin sequentially from July 15th. Please note that the distribution period may vary by store.)

The following Part 2 will start on July 22nd (Saturday)! 
This year, we will also distribute a shaved ice map! The "Gentle Ice of Minami Aso," made with carefully selected ingredients, is exquisite! This year, the number of participating stores has increased from 9 to a total of 10!
Of course, Part 2 will not be limited to just this! Stay tuned for more details coming soon!
(*The shaved ice map will be distributed starting July 22nd at participating stores and tourist information centers. Map data will be available from July 15th at the link below.)
https://minamiaso.info/blog/kakigori2023/

On hot days, why not come to Minami Aso to cool down with the proud creations of each store''s shaved ice?
We look forward to welcoming you all.
---------------------------------------------------
