update content_bodies set title = '南阿蘇村PV 2022 -Minamiaso Village PV 2022-', description = '南阿蘇村は、世界最大級の広さを誇る阿蘇カルデラの南麓に広がる「水の生まれる郷」です。
湧水とその恵みを受けて育つ豊かな農作物、田園風景の中を走る南阿蘇鉄道、豊富な泉質の温泉、そして千年以上にわたり放牧地として続いてきた草原とそこで暮らすあか牛など、ここでしか味わえない魅力にあふれています。

