update content_bodies set title = 'Every Day is Yoron 4K_Yoron Island, Nature moves on, as do we', description = 'WEB SITE
https://etooto.jp/

Winner of the Grand Prize at the 3rd Japan International Tourism Film Festival ART&FACTORY JAPAN

[Every Day is Yoron 4K_Yoron Island, Nature moves on, as do we]
The title "Every Day is Yoron = Nichinichi Kore Yoron" is an homage to the Zen phrase "Nichinichi Kore Kōjitsu" (to be grateful for each day and to live simply as it is). In 2020, after experiencing the pandemic, we have come to realize that "everyday life" is indeed a precious overlap of "special" moments.
Yoron Island, being a tourist destination, has certainly suffered greatly due to the pandemic, but this is true everywhere in the world.
Moreover, the island has overcome natural disasters such as annual typhoons and wars.
This work expresses the beauty and resilience of the island through the personification of various "lives" that inhabit Yoron Island, while accepting the great cycles of nature and repeating daily life. (That said, the daily life of Yoron may seem like a great non-everyday to those living in other cities).
From Yoron Island, we hope to send a message of encouragement to other remote islands and depopulated towns facing similar issues, and to all those living in the "now."

Director: Kentaro Kusunoki
Cinematography: Kentaro Kusunoki, Tomohiro Hebimi, Masaki Matsuda
Editing: Kentaro Kusunoki
Title Design: Gaku Higashi
Music: Takashi Watanabe
Poetry: Mika Murakami
English Title: Chiemi Fujii
Narration: Misa Nishihara
Sound Recording: Tomohiro Hebimi
Sound Editing: Ryo Idehara' where id = 'POtbnZikncqr9-tkmPQh1';
update content_bodies set title = 'ともによろこぶ Celebrate Tomonoura Together  -Japanese-【鞆の浦】', description = 'WEB SITE
https://etooto.jp/

鞆の浦のことを地元では「鞆＝とも」と呼びます。
日本語で「友」「朋」「共」といった響きを持つこの名には、鞆の浦の人びとが大切にしてきた自然との共生、家族や友だちと支え合いながら生きてきた言霊が宿ります。
本映像「時をともに」を通して、しばし、日本遺産認定「鞆の浦」に息づく穏やかでやさしい時間にお帰りください。

●第三章「ともによろこぶ」では、
のどかな港町が一丸となって盛り上がる10の祭事・神事を紹介。
よろこびをもって日々をくりかえす鞆の浦の暮らしに触れてみましょう。' where id = 'OzaDmGuzBjG7KXYXaiWnq';
update content_bodies set title = 'Celebrate Tomonoura Together -Japanese-【鞆の浦】', description = 'WEB SITE
https://etooto.jp/

In the local area, Tomonoura is referred to as "Tomo" (とも).
This name, which resonates with the sounds of "friend" (友), "companion" (朋), and "together" (共) in Japanese, embodies the spirit of coexistence with nature that the people of Tomonoura have cherished, as well as the bonds of support among family and friends.
Through this video "Together in Time," we invite you to return, if only for a moment, to the gentle and peaceful time that thrives in the Japan Heritage designated "Tomonoura."

● In Chapter 3, "Celebrate Together," we introduce 10 festivals and rituals that bring the tranquil port town together in celebration.
Let’s experience the life of Tomonoura, where joy is woven into the fabric of daily life.' where id = 'Jzyof3ozFbPLjXTUprVu2';
