update content_bodies set title = 'SNOW HIKE（スノーハイク）#ベンセ湿原', description = '気軽に雪を楽しみませんか？自由に雪上を散策しませんか？
「スノーハイク」をはいて、冬のベンセ湿原（青森県つがる市）を散策した様子をお届けします。
これまでスキーをしたことがなくても「スノーハイク」なら大丈夫。すぐに歩くことができます。ストレスも、運動不足も一緒に解消しましょう！

