update content_bodies set title = 'SNOW HIKE #Bense Wetland', description = 'Would you like to enjoy the snow casually? How about strolling freely on the snow? 
We present to you the experience of walking through the winter Bense Wetland (Tsugaru City, Aomori Prefecture) with ''Snow Hike''. 
Even if you have never skied before, ''Snow Hike'' is perfect for you. You can start walking right away. Let''s relieve stress and lack of exercise together!

Snow Hike (Blue Moris Co., Ltd.): https://bluemoris.com/bm/snowhike.html
Various tours using Snow Hike (4Ride): https://4ride-as.com/' where id = 'gijS1T-2UhLMcn9RLDR9x';
update content_bodies set title = '【AOMORI CYCLING】奥津軽ライド - OKUTSUGARU, JAPAN', description = '青森県・津軽半島の最北端「龍飛崎」を目指し、自転車で奥津軽を駆け抜けます。
自転車持ち込み可能な「津軽鉄道」を利用し芦野公園駅からスタート。千本鳥居が連なる「高山稲荷神社」、文豪・太宰治の生家「斜陽館」、黄金色の稲穂が美しい「米マイロード」、日本海を見下ろすダイナミックな景色が素晴らしい「竜泊ライン」、風情ある漁村など、見どころも走りごたえも満載なロングライドの様子をどうぞ。

※映像編集の都合上、芦野公園駅から龍飛崎まで行程が一筆書きではない箇所があります。

多様性ある青森でのサイクリング情報はこちらをご参考ください↓↓↓
AOMORI CYCLING Webサイト
https://aomori-cycling.com/' where id = 'UAYISnmkKXeS31sINFw96';
update content_bodies set title = '[AOMORI CYCLING] Okutsugaru Ride - OKUTSUGARU, JAPAN', description = 'We will ride through Okutsugaru on a bicycle, aiming for the northernmost point of the Tsugaru Peninsula, "Cape Tappi." 
Starting from Ashino Park Station using the "Tsugaru Railway," which allows bicycles, we will visit various attractions such as the "Takayama Inari Shrine" with its thousand torii gates, the birthplace of the literary giant Osamu Dazai, "Shayokan," the beautiful golden rice fields of "Kome My Road," the dynamic scenery overlooking the Japan Sea on the "Ryuhoku Line," and charming fishing villages. Enjoy the long ride filled with sights and challenges. 

*Due to video editing reasons, there are sections of the route from Ashino Park Station to Cape Tappi that are not a continuous line. 

For diverse cycling information in Aomori, please refer to the following: 
AOMORI CYCLING Website 
https://aomori-cycling.com/' where id = 'V5LVWzAdoIAx_9-RcmmC0';
