update content_bodies set title = 'DELISH AOMORI ''Fukaura Snow Carrot Potage''', description = 'The 11th installment of the recipe video series ''DELISH AOMORI'' brought to you by Marugoto Aomori. This time, the ingredient is ''Fukaura Snow Carrot'' grown in Fukaura Town. We have created a potage soup that deliciously captures the fruity sweetness that is almost unthinkable for a vegetable, while also savoring the flavor of the carrot itself. Please give it a try.
