update content_bodies set title = '【新島ミライプロジェクト】210402 CX Live News it!', description = '2021年春、東京の島　新島から島内全家庭のプラスティック洗濯バサミを、くさや型のアルミ製洗濯バサミ　”HOSSY" との交換を目指すプロジェクトです。

　紫外線で劣化し、すぐに壊れるプラスティック洗濯バサミを島のシンボルである”くさや型洗濯バサミ”に換えることにより、島の大切な産業である、くさやをより身近に感じてもらい、何より、もう壊れて捨てることのない洗濯バサミに交換することで、プラスティックのゴミを出さない生活へと変えていきたいと考えています。

海から恵みをいただき発展してきた島だから、「今こそ自然環境に対し、何ができるか？」を島の人たち一人一人が考える機会の創出です。

　今後は、東京宝島の力もお借りし、同時に企業様の力もお借りしたいと願っております。もちろん私たちでもクラウドファンディングを行い、少しでも多くの方にコミットいただきたいと考えています。

そして新島での取り組みを、東京諸島の全11島へ広げ、その先にこのアクションを日本の島々へ広めて行きたいと考えております。
狙いは2つ。

①日本の食文化への理解 “干物（くさや）”から、郷土への誇りを高めるとともに、
②難しく考えがちな “環境問題”をユニークな取組みで、気づきの連鎖につなげたい。

それは【新しい、でつながる島】だから。
海と生きるまち。海の環境問題に正面から取り組む「エコアイランド構想」への環境アクションです。' where id = 'H3pOK8101_fC--sC05qCa';
update content_bodies set title = '[Niijima Mirai Project] 210402 CX Live News it!', description = 'In spring 2021, this project aims to exchange plastic laundry clips from all households on Niijima Island, Tokyo, for aluminum laundry clips shaped like kusaya, called ''HOSSY''.

By replacing plastic laundry clips, which deteriorate under UV light and break easily, with the island''s symbol, the ''kusaya-shaped laundry clip'', we hope to make the important industry of kusaya more familiar to everyone. Most importantly, by exchanging for laundry clips that won''t break and be thrown away, we aim to transition to a lifestyle that produces no plastic waste.

As an island that has developed by receiving blessings from the sea, we want to create opportunities for each islander to think about ''What can we do for the natural environment now?''.

In the future, we hope to leverage the power of Tokyo''s Treasure Island and also seek the support of companies. Of course, we plan to conduct crowdfunding ourselves, hoping to get as many people as possible to commit to this cause.

We also aim to expand our efforts on Niijima to all 11 islands of the Tokyo Islands, and ultimately spread this action to the islands of Japan.
There are two main objectives:

1. To enhance understanding of Japan''s food culture through ''dried fish (kusaya)'' and foster pride in our local heritage.
2. To connect the often complex topic of ''environmental issues'' to a chain of awareness through unique initiatives.

This is because it is [a new island connected by innovation].
A town that lives with the sea. This is an environmental action towards the ''Eco-Island Concept'', which directly addresses marine environmental issues.' where id = 'w0Su2RrNFcmJCFHk0wopa';
update content_bodies set title = '【秋田市プロモーションビデオ④】よそものを大切にしてくれるまち「式田」 short ver.', description = '雄物川が運んだ文化が花開く「新波」、秋にはこがね色の絨毯が広がる里「式田」。秋田市シティプロモーションモデル事業の一環として行ったワークショップを通し、地域住民が主体となってみつけたそれぞれの地区の『魅力』を詰め込んだ映像です。

～よそものを大切にしてくれるまち「式田」～
お金より大事な何かを探しに来た写真家。
長年の夢を追いかけにきたサラリーマン。
笑顔を運んでくれる、学生や若者たち。
まちが受け入れてくれる、大切にしてくれる。
秋田市河辺・式田で、大切なことを見つけました。

【新波編】https://youtu.be/g9Vh2qf_MF0
【新波編ショートバージョン】https://youtu.be/XRoiXmMBKTo
【式田編」https://youtu.be/uGzoFvgbjLg' where id = '7QvsSuseUe_0eIn0JP8zj';
update content_bodies set title = '[Akita City Promotion Video ④] A Town That Values Outsiders ''Shikida'' Short Version', description = 'In ''Shinami'', where the culture brought by the Omorogawa River flourishes, and in ''Shikida'', a village where a golden carpet spreads in autumn. This video is filled with the ''charm'' of each area discovered by local residents through workshops conducted as part of the Akita City City Promotion Model Project.

~ A Town That Values Outsiders ''Shikida'' ~
A photographer who came to find something more important than money.
A salaryman who came to chase a long-held dream.
Students and young people who bring smiles.
The town accepts and cherishes them.
In Akita City, Kabe and Shikida, we found something precious.

