update content_bodies set title = '伝統の技　秋田の竿燈　　KANTO', description = '国の重要無形民俗文化財で、東北三大祭りにも数えられる秋田市の夏の風物詩。秋田竿燈まつりは毎年８月３日から６日まで、竿燈大通りで行われています。力４、技６、竿燈を思いのまま操る差し手の妙技と、秋田市の夜空を黄金色に彩る光の稲穂の幻想的な風景を是非一度、秋田でご覧ください。

平成２５年度　広報広聴課制作

秋田竿燈まつり
http://www.kantou.gr.jp/index.htm' where id = 'uvtcXMWwQT5NKzLgdWqKu';
update content_bodies set title = 'Traditional Craft: Akita Kanto', description = 'A summer tradition of Akita City, recognized as an Important Intangible Folk Cultural Asset of the country and counted among the three major festivals of Tohoku. The Akita Kanto Festival is held every year from August 3rd to 6th on Kanto Avenue. Experience the skillful techniques of the performers who manipulate the Kanto with strength and finesse, and witness the enchanting landscape of golden rice ears illuminating the night sky of Akita.' where id = '1-eCTnGyCZuRga5z2nhjT';
