update content_bodies set title = '秋田市觀光宣傳影片「Life is a Journey(人生是一場旅程)」短篇', description = '以生活在秋田市的一對夫婦的視角來描繪的小短劇，精心打造的觀光宣傳影片「Life is a Journey(人生是一場旅程)」

「人生是一場旅程」

帶著好奇心度過每一天，每天就像旅行一樣……
每個小小的發現都能讓日常生活更加閃閃發光。

