update content_bodies set title = 'Spring in Nagoya', description = 'コロナ禍により観光渡航が途絶する中、早春の名古屋の美しさを感じていただきたく、春の精に誘われるイメージで動画を作成しました。
乾杯のシーンでは、VYSA Tokai（在日ベトナム学生青年協会東海支部）のメンバーにご協力いただきました。' where id = 'E69ESguTlN4jaMmEqdlkY';
update content_bodies set title = 'Spring in Nagoya', description = 'Amidst the pandemic that has halted tourism, we created a video to convey the beauty of early spring in Nagoya, inspired by the spirit of spring.
In the scene of the toast, we received cooperation from members of VYSA Tokai (Vietnamese Youth and Student Association Tokai Branch).' where id = 'npYH9bwh8G1wvk-f7Z1jv';
update content_bodies set title = '名古屋神社めぐり旅', description = '愛知県は神社仏閣の数が日本一だということはご存じでしょうか？
そんな神社仏閣の多いエリアにおいて、名古屋市内には700以上の「神社」が鎮座しています。
神社はその土地の歴史に縁が強く、いろいろな物語を楽しむことができます。
