名古屋の「伝統」と「近未来」的な魅力が融合した動画が完成しました。
コンセプトは「COOL! NAGOYA」。
歴史、食、ナイトタイム観光、ウェルネス、アミューズメントの魅力の紹介に、名古屋発祥の和楽器「大正琴」の音色を取り入れて、DJ/プロデューサーのYamatoが生み出すオリジナルのエレクトロニック・ダンスミュージックに乗せて紹介します。
ぜひ楽しんでください！
※新型コロナウイルス感染症対策に留意して撮影しています。

