update content_bodies set title = '【イルミ×AR】なんばに、誰も体験したことのない感動を。', description = 'なんばの冬の夜空を彩る風物詩「なんば光旅」。そのメインスポットであるなんばパークスの光の滝で、他社と共創しながら、AR技術を用いて日本初に挑戦する姿を描いたショートムービーです。南海グループでは、ブランドスローガン「‘なんかいいね’があふれてる」をもとに、 これからも人やまち、そして未来にたくさんの‘なんかいい’をお届けしていきます。

