update content_bodies set title = '[Illumination × AR] Experience an emotion like never before in Namba.', description = 'The winter night sky of Namba is adorned with the seasonal event ''Namba Light Journey.'' This is a short movie depicting our challenge to be the first in Japan using AR technology, in collaboration with other companies, at the main spot, the Light Waterfall of Namba Parks. The Nankai Group, based on our brand slogan ''Overflowing with something good,'' will continue to deliver many ''something good'' to people, towns, and the future.' where id = 'o6RoLyUH4uxIYVtUy5Jrh';
update content_bodies set title = '日本の産業を巡る旅へ！Journey Through Japanese Industries', description = 'From South Osaka to Wakayama, we offer two unique plans of Industrial Tourism: the Superior Plan, where you can engage in direct conversations with business owners, learning their secrets of business succession, sustainable manufacturing, and remarkable recovery from global financial crises; and the Standard Plan, which provides a behind-the-scenes look at traditional industries. 
Join us on a journey to discover the heart of Osaka’s craftsmanship and passion.

Please contact us from the URL below.
https://matcha-jp.com/jp/23218
------------------------------------------------
What is Industrial Tourism?
★Discover the Hidden Side of Japan’s Manufacturing
Osaka is where products showcasing the skills of Japan’s proud craftsmen are created. You can experience a wide range of factories, from traditional crafts to metal processing. Take a step inside to the actual workshops.

★Learn from the Leaders of Long-Established Companies
Executives from companies with over 50 years of history will personally explain the secrets of their insights -environmentally friendly manufacturing, methods for training young talent, business succession strategies, and more.

★Optimal Location in Osaka
The companies are located between Kansai Intl Airport and Namba, offering excellent access.

For more information/enquiries, check our website :https://matcha-jp.com/en/23218

南大阪・和歌山エリアの企業を訪問する特別ツアーです。プレミアムプランでは経営者との対話を通じて事業承継や製造業の展望を学び、スタンダードプランでは伝統産業の現場見学ができます。
大阪のものづくりの真髄に触れる貴重な機会をお届けします。

産業観光とは？
★ものづくり大国ニッポンの裏側に潜入！
日本が誇る職人の技術がつまった製品が生み出されている場所ーそれが、関西です。
伝統工芸品からプラスチックや金属加工品まで、幅広いものづくりの現場を見学・体験いただけます。
見学いただける工場は、優れた技術とイノベーティブな経営者がいるものづくり企業。世界から信頼されている日本の製品が生まれている生の現場に潜入いただきます。

★長寿企業の経営者から学ぶ体験を
　50年以上の歴史を誇る企業の経営層が皆さまをお迎えし、環境共生型のものづくりの秘訣や、若手人材の確保/育成方法、３Ｓの徹底、事業承継の方法など、社長自らご説明いたします。
　
★関西国際空港と大阪万博の間の最適なロケーションで体験　
弊社がご提案するものづくり企業の多くは、関西の玄関口・関西国際空港と、
大阪の中心地・なんばの間に位置しているため、アクセス抜群。

詳細について/お問合せはこちらから：https://matcha-jp.com/jp/23218' where id = 'k78TB1OGlr7mxK7WMeQx_';
update content_bodies set title = 'Journey Through Japanese Industries', description = 'From South Osaka to Wakayama, we offer two unique plans of Industrial Tourism: the Superior Plan, where you can engage in direct conversations with business owners, learning their secrets of business succession, sustainable manufacturing, and remarkable recovery from global financial crises; and the Standard Plan, which provides a behind-the-scenes look at traditional industries.
Join us on a journey to discover the heart of Osaka’s craftsmanship and passion.

Please contact us from the URL below.
https://matcha-jp.com/jp/23218
------------------------------------------------
What is Industrial Tourism?
★Discover the Hidden Side of Japan’s Manufacturing
Osaka is where products showcasing the skills of Japan’s proud craftsmen are created. You can experience a wide range of factories, from traditional crafts to metal processing. Take a step inside to the actual workshops.

★Learn from the Leaders of Long-Established Companies
Executives from companies with over 50 years of history will personally explain the secrets of their insights - environmentally friendly manufacturing, methods for training young talent, business succession strategies, and more.

★Optimal Location in Osaka
The companies are located between Kansai Intl Airport and Namba, offering excellent access.

For more information/enquiries, check our website :https://matcha-jp.com/en/23218

This is a special tour visiting companies in the South Osaka and Wakayama area. In the Premium Plan, you can learn about business succession and the outlook for the manufacturing industry through dialogue with business owners, while the Standard Plan offers a tour of traditional industries.
We provide a valuable opportunity to touch the essence of Osaka''s craftsmanship.

What is Industrial Tourism?
★Dive into the Hidden Side of Japan’s Manufacturing!
This is where products filled with the skills of Japan''s proud craftsmen are created - that is Kansai.
You can visit and experience a wide range of manufacturing sites, from traditional crafts to plastic and metal processing.
The factories you will visit are manufacturing companies with excellent technology and innovative management. You will have the chance to enter the live sites where trusted Japanese products are born.

★Experience Learning from the Executives of Long-Established Companies
Executives from companies with over 50 years of history will welcome you and personally explain the secrets of environmentally friendly manufacturing, methods for securing and training young talent, thorough implementation of 3S, and business succession methods.

★Experience in an Optimal Location between Kansai International Airport and Osaka Expo
Many of the manufacturing companies we propose are located between Kansai International Airport, the gateway to Kansai, and Namba, the center of Osaka, ensuring excellent access.

For more details/inquiries, please contact us here: https://matcha-jp.com/jp/23218' where id = 'o341Mmey_ax0QOVFLUmOP';
