update content_bodies set title = 'まちの参観日in河内長野（オンラインイベント）', description = '2024年9月7日に実施した、まちの参観日in河内長野オンラインイベントのアーカイブ動画です。

南海電鉄と一緒に沿線の魅力を発見・発信する「南海電鉄地域発見クリエイターズ課」が、大阪府河内長野市の魅力を市内各所からLIVE中継でお伝えしたオンラインイベント。当日は約500名にも及ぶ全国のお客さまにご視聴いただきました！
是非ご覧ください。

■目次（タイムスケジュール）
0:00　オープニング
9:51　ワークワクワク河内長野
20:21　子育て支援施設「あいっく」
30:59　奥河内くろまろの郷エリア
43:56　花の文化園
51:05　エンディング

