update content_bodies set title = 'Namba EKIKAN Project Making Movie (Released in 2014)', description = 'This is the making movie of the ''Namba EKIKAN Project,'' which renovated part of the elevated area between Nankai Namba Station and Imamiya Ebisu Station in Osaka.
