update content_bodies set title = 'OKINAWA travel film', description = 'Okinawa travel film - This video was created using footage captured during a study tour in Okinawa in February 2024. The footage showcases Okinawa''s captivating landscapes, traditional culture, and various experiences from the study tour. Through this video, we hope to share a glimpse of Okinawa''s rich charm with you.

2024年2月に沖縄のスタディツアーに参加した際に撮影した素材を使用し、動画を制作しました。撮影した映像には、沖縄の魅力的な風景や伝統文化、スタディツアー中のさまざまな体験が詰め込まれています。この動画を通じて、沖縄の豊かな魅力を少しでもお伝えできれば幸いです。


【Special Thanks - 撮影協力】
