【About Unexpected Japan】
Unexpected Japan is a creative promotion team specializing in inbound promotion services operated by Ayabex inc., a travel agency in Japan (DMC). As a travel agency making use of the knowledge gained in the DMC experience, we provide one-stop services such as tour creation, video/image production, online tour/seminar service, and tour sales platforms by our inbound travel professionals. Through our creation and production, including video and imagery, design and tour content, we will serve as a bridge between overseas and Japan, and help you to find your encounter with unexpected Japan.

Unexpected Japanは、訪日旅行会社（通称DMC）であるアヤベックス株式会社が運営するインバウンドプロモーションサービスに特化したクリエイティブチームです。DMC業で得た知見を活かした旅行会社ならではの目線で、インバウンドのプロが提案するツアー造成・映像制作・オンライン配信・コンテンツ販売等のサービスを、ワンストップで提供しています。

ローカルツーリズムをはじめとした、映像やデザインコンテンツ制作・ツアー造成を通して、海外と日本の架け橋となり、本物の日本との出会いをみつけるお手伝いを致します。

Contact : 
https://unexpected-japan.com/
https://ayabex.com/
Instagram : 
https://www.instagram.com/unexpected.japan/

