update content_bodies set title = '【Майдзуру Киото】【Maizuru Kyoto】East Side Story / Travel in Japan / Cinematic Travel Vlog 舞鶴観光PR動画', description = 'English and Japanese below


Город Майдзуру - портовый город на севере префектуры Киото. В этом ролике мы расскажем о восточной части города. Она имеет долгую историю в качестве базы военного флотв со времён эпохи Мэйдзи, и благодаря ей "Морской пейзаж с военными кораблями" стал символом города Майдзуру. В городе с давних времен сохранилось большое количество памятников, связанных с флотом.  Здесь вы можете увидеть как голубое море, так и историческое наследие.
Обязательно посмотрите видео о Восточном Майдзуру.


Благодарим за помощь в организации съёмок Ассоциацию туризма города Майдзуру.
Большое спасибо всем, кто помогал нам в съёмках!


Подписывайтесь на наш канал!

► YouTube   https://www.youtube.com/channel/UCgJ1fenTgwsTDNgfQ1egFlw
► Instagram https://www.instagram.com/_unexpected_japan_/
► Twitter   https://twitter.com/JapanUnexpected
► Facebook  https://www.facebook.com/Unexpected-Japan-102942654851907/


Канал Unexpected Japan ведётся специализированной туристической компанией Аябэкс. Мы хотим показать вам красоту Японии, какой её видим мы – профессионалы туризма. Запросы о сотрудничестве можно отправлять на почту  unexpected-japan@ayabex.com




