 舞鶴市は京都府の北端に位置する港町、この動画では舞鶴の東側を紹介しています。
ここは明治時代から軍港としての長い歴史があり、「軍艦のある海」がまさに舞鶴のトレードマークです。市内には古くから海軍ゆかりの史跡が多く残り、青い海と共に歴史を感じる美しい風景を紹介しています。
ぜひ東舞鶴の魅力溢れる動画をお楽しみください。

制作協力：舞鶴観光協会　　
撮影にご協力頂いた皆様、本当にありがとうございました！

