update content_bodies set title = '[Maizuru Kyoto] East Side Story / Travel in Japan / Cinematic Travel Vlog Maizuru Tourism PR Video', description = 'English and Japanese below

The city of Maizuru is a port city located in the northern part of Kyoto Prefecture. In this video, we will introduce the eastern part of the city. It has a long history as a naval base since the Meiji era, and because of this, the "Seascape with Warships" has become a symbol of the city of Maizuru. The city has preserved many monuments related to the navy since ancient times. Here you can see both the blue sea and historical heritage. 
Be sure to watch the video about East Maizuru.

We thank the Maizuru Tourism Association for their assistance in organizing the filming. 
A big thank you to everyone who helped us with the filming!

