Maizuru City is a port town located at the northern end of Kyoto Prefecture, and this video introduces the eastern side of Maizuru. 
This area has a long history as a naval port since the Meiji era, and "the sea with warships" is truly the trademark of Maizuru. The city has many historical sites related to the navy, and we are showcasing beautiful scenery that evokes a sense of history along with the blue sea. 
Please enjoy the captivating video of East Maizuru.

Production cooperation: Maizuru Tourism Association 
Thank you very much to everyone who cooperated with the filming!

