update content_bodies set title = 'Shigaraki Pottery & Hikone History Japan Travel  Cinematic Vlog / 滋賀＆福井周遊 vol.2 土鍋ごはんと信楽焼工房見学・彦根観光', description = 'Our travel in Shiga is continuing from our last video.
We visited a restaurant where they serve rice in earthen pots of Shigaraki ware which is one of Japanese pottery and a workshop.

