update content_bodies set title = 'looking for the shine 輝きを探して　ふくい嶺北連携中枢都市圏 景観PR映像 第７弾', description = '北陸新幹線福井開業に向け、ふくい嶺北連携中枢都市圏において、景観PR映像を制作しています。

【映像内容】
（テーマ）
ファインダーのむこう、輝きを探して

（解説）
理想の写真を追い求めひたむきに取り組むフォトグラファーの姿と、新しい時代の到来を予感させる光を帯びた街を映し出します。

（動画の目次）
0:00　オープニング
0:12　足羽川桜並木　 Asuwa River Cherry Tree Row （福井市）
0:23　九頭竜川と新九頭竜橋　Kuzuryu River & Shin-Kuzuryu Bridge（福井市）
0:31　村国山展望台　Observatory of Mt.Murakuni（越前市）
0:36　南条の花はす　Lotus Flowers（南越前町）
0:45　北潟の風車　Windmill（あわら市）
0:52　日野山と日野川　Mt.Hino & Hino River（越前市）
0:57　さばえ菜花米の田園　Fields of Sabae Nabanamai（鯖江市）
1:02　足羽川と福井市のまちなみ　Asuwa River & Fukui Cityscape（福井市）
1:09　三床山の雲海　Sea of Clouds of Mt.Mitoko（鯖江市）
1:15　宮谷石切場跡　Miyadani Quqrry Ruins（あわら市）
1:25　一面に広がるそば畑　A field of buckwheat spread all over（坂井市）
1:31　越廼の越前水仙　Echizen Narcissus（福井市）
1:34　足羽川の若鮎の遡上　Ayu Sweatfish swimming upstream（福井市）
1:40　北陸新幹線
2:10　撮影地紹介

（出演）
友㟢 雄太（写真家）
福井市出身。２０２２年、写真集「あの頃にみた青は、」「撮りたい世界が地元にある」を出版。
