update content_bodies set title = '【鹿児島30秒ver】BREATHTAKING KAGOSHIMA〜心奪われる鹿児島〜', description = '#鹿児島 #桜島 #4K

雄大で美しい自然，古くからあった海外との交流を経て発展した食文化，火山が生み出す豊富な温泉，かつて国をも動かすに至った歴史，多彩な魅力を有する離島など，豊富な地域資源を有する鹿児島。自然に守られ、人の手によって守られ、鹿児島の日常が続いていく。

Kagoshima is blessed by bountiful volcanic landscapes, a unique food culture influenced by ancient exchanges with distant lands, bubbling natural hot springs, and a history that shaped the future of Japan. Remote tropical islands waiting to be explored dot the southern seas, each with their own unique culture and customs. Discover the daily life of the local people and lose yourself in Kagoshima.

【BREATHTAKING KAGOSHIMA～心奪われる鹿児島～】
